if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !convert <value> <from> <to>\n\nSupported:\nkg ↔ lb | km ↔ mi | °C ↔ °F | L ↔ gal | cm ↔ in | m ↔ ft');
const parts = argumentName.trim().split(/\s+/);
if (parts.length < 3) return sendTrackedMessage(sock, remoteJid, 'Usage: !convert 100 kg lb');
const val = parseFloat(parts[0]);
if (isNaN(val)) return sendTrackedMessage(sock, remoteJid, '❌ Invalid number.');
const from = parts[1].toLowerCase();
const to = parts[2].toLowerCase();
const conversions = {
  'kg-lb': v => v * 2.20462,
  'lb-kg': v => v / 2.20462,
  'km-mi': v => v * 0.621371,
  'mi-km': v => v / 0.621371,
  'c-f': v => v * 9/5 + 32,
  'f-c': v => (v - 32) * 5/9,
  'l-gal': v => v * 0.264172,
  'gal-l': v => v / 0.264172,
  'cm-in': v => v / 2.54,
  'in-cm': v => v * 2.54,
  'm-ft': v => v * 3.28084,
  'ft-m': v => v / 3.28084,
};
const key = `${from}-${to}`;
if (!conversions[key]) return sendTrackedMessage(sock, remoteJid, '❌ Unsupported conversion. Type !convert for help.');
const result = conversions[key](val);
await sendTrackedMessage(sock, remoteJid, `📐 ${val} ${from} = ${result.toFixed(4)} ${to}`);
